def merge_flags(base, override):
    base.update(override)
    return base

from src.marigold_triage import merge_flags

base = {'debug': False, 'port': 8000}
override = {'debug': True}
result = merge_flags(base, override)
assert result == {'debug': True, 'port': 8000}
assert base == {'debug': False, 'port': 8000}

